CREATE INDEX sync_fdf2cac8555825a37edee87d5d45_replica_changes_key ON sync_fdf2cac8555825a37edee87d5d45_replica_changes(key);
CREATE TRIGGER "sync_fdf2cac8555825a37edee87d5d45_track_0_delete" AFTER DELETE ON "jelly_workspace" BEGIN INSERT INTO sync_fdf2cac8555825a37edee87d5d45_replica_changes(key) SELECT key FROM (SELECT json_array('jelly','workspace') AS key WHERE OLD."revision" > 0) WHERE (SELECT applying FROM sync_fdf2cac8555825a37edee87d5d45_replica_state WHERE id=1)=0; END;
CREATE TRIGGER "sync_fdf2cac8555825a37edee87d5d45_track_0_insert" AFTER INSERT ON "jelly_workspace" BEGIN INSERT INTO sync_fdf2cac8555825a37edee87d5d45_replica_changes(key) SELECT key FROM (SELECT json_array('jelly','workspace') AS key WHERE NEW."revision" > 0) WHERE (SELECT applying FROM sync_fdf2cac8555825a37edee87d5d45_replica_state WHERE id=1)=0; END;
CREATE TRIGGER "sync_fdf2cac8555825a37edee87d5d45_track_0_update" AFTER UPDATE ON "jelly_workspace" BEGIN INSERT INTO sync_fdf2cac8555825a37edee87d5d45_replica_changes(key) SELECT key FROM (SELECT json_array('jelly','workspace') AS key WHERE NEW."revision" > 0) WHERE (SELECT applying FROM sync_fdf2cac8555825a37edee87d5d45_replica_state WHERE id=1)=0;INSERT INTO sync_fdf2cac8555825a37edee87d5d45_replica_changes(key) SELECT key FROM (SELECT json_array('jelly','workspace') AS key WHERE OLD."revision" > 0 EXCEPT SELECT json_array('jelly','workspace') AS key WHERE NEW."revision" > 0) WHERE (SELECT applying FROM sync_fdf2cac8555825a37edee87d5d45_replica_state WHERE id=1)=0; END;
